function buildArb(locale) {
  const arb = { '@@locale': locale };
  for (const [key, entry] of Object.entries(catalog)) {
    arb[key] = entry[locale];
    if (entry.placeholders) {
      arb[`@${key}`] = { placeholders: entry.placeholders };
    }
  }
  return JSON.stringify(arb, null, 2) + '\n';
}

const apps = ['tranoo', 'tranoo_pro'];
for (const app of apps) {
  const dir = path.join(__dirname, '..', app, 'lib', 'l10n');
  fs.writeFileSync(path.join(dir, 'app_en.arb'), buildArb('en'));
  fs.writeFileSync(path.join(dir, 'app_fr.arb'), buildArb('fr'));
  fs.writeFileSync(path.join(dir, 'app_ar.arb'), buildArb('ar'));
  console.log(`Generated ARB for ${app} (${Object.keys(catalog).length} keys)`);
}
